it('caches dynamic schemas by object reference specs/hal-engine-tool-input-validation/spec.md#7', async () => {
  const registry = new ToolRegistry();
  const schema = {type: 'object'};
  const compile = jest.spyOn(Ajv.prototype, 'compile');
  registry.register(
    () => ({name: 'dynamic', description: 'dynamic', inputSchema: schema}),
    async () => 'ok'
  );
  await registry.execute('dynamic', {});
  await registry.execute('dynamic', {});
  const calls = compile.mock.calls;
  expect(calls.filter(([arg]) => arg === schema)).toHaveLength(1);
  compile.mockRestore();
});
