it('rejects missing required input specs/hal-engine-tool-input-validation/spec.md#1', async () => {
  const registry = new ToolRegistry();
  const execute = jest.fn(async () => 'success');
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
    },
    execute
  );
  const response = await registry.execute('weather', {});
  expect(response.result).toMatch(/location.*required|required.*location/i);
  expect(execute).not.toHaveBeenCalled();
});
