import {createProvider} from './providerFactory.js';
import type {ResponseSchema, StructuredOutputParams} from '../types/ai.js';

// An arm that drops its argument stays invisible until compared against the direct factory.
const SCHEMA: ResponseSchema = {type: 'object', properties: {status: {type: 'string'}, count: {type: 'number'}}};

const structuredParams = (content: string): StructuredOutputParams<unknown> => ({
  messages: [{role: 'user', content}],
  systemPrompt: 'system',
  responseSchema: SCHEMA,
});

const configuredMock = () =>
  createProvider({type: 'mock', structuredResponses: new Map([['ping', {status: 'configured', count: 42}]])});

describe('createProvider', () => {
  it('forwards MockConfig, so a configured structured response survives the factory', async () => {
    await expect(configuredMock().generateStructured(structuredParams('ping'))).resolves.toEqual({
      status: 'configured',
      count: 42,
    });
  });

  it('falls back to schema-shaped defaults for a message the map does not name', async () => {
    await expect(configuredMock().generateStructured(structuredParams('unmapped'))).resolves.toEqual({
      status: '',
      count: 0,
    });
  });

  it('accepts a mock config carrying no map at all', async () => {
    const provider = createProvider({type: 'mock'});

    await expect(provider.generateStructured(structuredParams('ping'))).resolves.toEqual({status: '', count: 0});
  });

  it('dispatches each arm to a provider satisfying the full AIProvider interface', () => {
    const shape = (provider: unknown) => {
      const p = provider as Record<string, unknown>;
      return typeof p.sendMessage === 'function' && typeof p.generateStructured === 'function';
    };

    expect([
      shape(createProvider({type: 'mock'})),
      shape(createProvider({type: 'openai', apiKey: 'k', model: 'm'})),
      shape(createProvider({type: 'anthropic', apiKey: 'k', model: 'm'})),
      shape(createProvider({type: 'bedrock', region: 'eu-west-1', modelId: 'm', maxTokens: 16})),
      shape(createProvider({type: 'vertex', projectId: 'p', location: 'europe-west4', modelId: 'm'})),
    ]).toEqual([true, true, true, true, true]);
  });

  it('routes the mock arm to the mock, not to a neighbouring arm', async () => {
    const chunks = [];
    for await (const chunk of createProvider({type: 'mock'}).sendMessage({
      messages: [{role: 'user', content: 'hi'}],
      systemPrompt: 'system',
    })) {
      chunks.push(chunk.type);
    }

    expect(chunks[chunks.length - 1]).toBe('stop');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects missing required input specs/hal-engine-tool-input-validation/spec.md#1](../../src/orchestration/tools/registry.validation.test.ts#L4), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: rejects an invalid static schema at registration specs/hal-engine-tool-input-validation/spec.md#5](../../src/orchestration/tools/registry.test.ts#L4), [validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: caches dynamic schemas by object reference specs/hal-engine-tool-input-validation/spec.md#7](../../src/orchestration/tools/registry.cache.test.ts#L5)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

